async function authed(req,env,c){if(!c)return false;const k=cookies(req).hs;return !!k&&eq(k,c.session);}
async function serveObj(req,env,key,dl,name){
  const head=await env.FILES.head(key);if(!head)return new Response('לא נמצא',{status:404});
  const size=head.size;const h=new Headers(SEC);head.writeHttpMetadata(h);h.set('etag',head.httpEtag);h.set('accept-ranges','bytes');h.set('cache-control','private, max-age=86400');
  const fn=name||key.split('/').pop();const ascii=key.split('/').pop();
  h.set('content-disposition',`${dl?'attachment':'inline'}; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(fn)}`);
  const ct=h.get('content-type')||'';if(ct.startsWith('text/')&&!ct.includes('charset'))h.set('content-type',ct+'; charset=utf-8');
  const rh=req.headers.get('range');
  if(req.method==='HEAD'){h.set('content-length',String(size));return new Response(null,{status:200,headers:h});}
  if(rh){const m=/^bytes=(\d*)-(\d*)$/.exec(rh.trim());let s,e;
    if(m){if(m[1]===''){const n=+m[2];s=Math.max(0,size-n);e=size-1;}else{s=+m[1];e=m[2]===''?size-1:Math.min(+m[2],size-1);}}
    if(!m||s>e||s>=size){h.set('content-range',`bytes */${size}`);return new Response(null,{status:416,headers:h});}
    const o=await env.FILES.get(key,{range:{offset:s,length:e-s+1}});
    h.set('content-range',`bytes ${s}-${e}/${size}`);h.set('content-length',String(e-s+1));return new Response(o.body,{status:206,headers:h});}
  const o=await env.FILES.get(key);h.set('content-length',String(size));return new Response(o.body,{status:200,headers:h});}
async function coreManifest(env){const o=await env.FILES.get('_manifest.json');return o?JSON.parse(await o.text()):{title:'',folders:[],files:[]};}
async function contribEntries(env){const keys=[];let cur;do{const l=await env.FILES.list({prefix:'_contrib/',cursor:cur,limit:1000});l.objects.forEach(o=>keys.push(o.key));cur=l.truncated?l.cursor:null;}while(cur);
  const out=await Promise.all(keys.map(async k=>{try{const o=await env.FILES.get(k);return o?JSON.parse(await o.text()):null;}catch(e){return null;}}));
  return out.filter(Boolean).sort((a,b)=>String(a.added).localeCompare(String(b.added)));}
async function manifest(env){const m=await coreManifest(env);const cs=await contribEntries(env);const ids=new Set(m.files.map(f=>f.id));
  cs.forEach(e=>{if(!ids.has(e.id))m.files.push(e);});
  if(cs.some(e=>e.folder&&e.folder[0]===DEFAULT_FOLDER)&&!m.folders.some(f=>f.path.length===1&&f.path[0]===DEFAULT_FOLDER))m.folders.push({path:[DEFAULT_FOLDER],icon:'📥'});
  return m;}
