// ---- settings: title / owner / footer brand / feedback email, filled into every page at response time ----
const DEF_SETTINGS={title:'הדרייב שלי',owner:'מורה',brand:'',brand_url:'',feedback_email:''};
let ST_CACHE=null,ST_AT=0;
function cleanSetting(k,v){v=String(v==null?'':v).replace(k==='brand_url'?/[<>"'`\\\s]/g:/[<>"'`\\&\u0000-\u001f]/g,'').trim().slice(0,k==='brand_url'?300:80);
  if(k==='brand_url'&&v&&!/^https?:\/\/\S+$/.test(v))return '';if(k==='feedback_email'&&v&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))return '';return v;}
